 if($type==='payments'){$q=$pdo->prepare('SELECT id,paid_on,amount_cents,bank_transaction_id,description FROM estate_payments WHERE paid_on BETWEEN ? AND ? ORDER BY paid_on,id LIMIT 10001');$q->execute([$from,$to]);$header=['Private Zahlungs-ID','Datum','Betrag EUR','Privater Bankumsatz-ID','Beschreibung'];$rows=$q->fetchAll();foreach($rows as &$r)$r['amount_cents']=financeDecimal((int)$r['amount_cents']);unset($r);}
