 else throw new RuntimeException();if(count($rows)>10000)throw new RuntimeException('Zeitraum verkleinern.');$out="\xEF\xBB\xBF";foreach([$header,...array_map('array_values',$rows)] as $row)$out.=implode(';',array_map('invCsvCell',$row))."\r\n";
